#!/usr/bin/env python3
"""pre-commit `commit-msg` stage hook — validates the commit message subject line against
this repo's convention: `tipo: #ticket descripción` (CONTRIBUTING.md).

pre-commit passes the path to the commit-message file as argv[1] for this stage."""

import re
import sys

_PATTERN = re.compile(
    r"^(feat|fix|chore|refactor|test|docs|perf|style|build|ci|revert)"  # tipo
    r"(\([a-z0-9_-]+\))?"  # scope opcional: feat(orders): ...
    r": #[A-Za-z0-9-]+ .+"  # #ticket descripción
)

# Merge commits, revert commits generated by `git revert`, and fixup!/squash! markers used
# during interactive rebase all have their own well-known shapes — not worth forcing them
# through this convention.
_SKIP_PREFIXES = ("Merge ", "Revert ", "fixup!", "squash!")


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print("check_commit_message.py: falta la ruta del archivo de mensaje.", file=sys.stderr)
        return 1

    with open(argv[1], encoding="utf-8") as f:
        subject = f.readline().strip()

    if not subject or subject.startswith(_SKIP_PREFIXES):
        return 0
    if _PATTERN.match(subject):
        return 0

    print(
        f"Mensaje de commit inválido: '{subject}'\n"
        "Formato esperado: tipo: #ticket descripción\n"
        "tipo: feat | fix | chore | refactor | test | docs | perf | style | build | ci | revert\n"
        "Ejemplo: feat: #482 agrega endpoint de cancelación de orden\n"
        "Ver CONTRIBUTING.md.",
        file=sys.stderr,
    )
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
